#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>
#include <cstdint>

namespace {

constexpr unsigned WARP = 32u;
constexpr unsigned WARP_MASK = 0xffffffffu;
constexpr int kB = 16;
constexpr int kT = 512;

__device__ __forceinline__ unsigned saddr(const void* p) {
  return static_cast<unsigned>(__cvta_generic_to_shared(p));
}
__device__ __forceinline__ unsigned remap(const void* p, unsigned r) {
  unsigned a; asm(\"mapa.shared::cluster.u32 %0, %1, %2;\" : \"=r\"(a) : \"r\"(saddr(p)), \"r\"(r)); return a;
}
__device__ __forceinline__ void red_remote(unsigned a, unsigned v) {
  asm volatile(\"red.relaxed.cluster.shared::cluster.add.u32 [%0], %1;\" :: \"r\"(a), \"r\"(v) : \"memory\");
}
__device__ __forceinline__ void st_remote(unsigned a, unsigned v) {
  asm volatile(\"st.shared::cluster.u32 [%0], %1;\" :: \"r\"(a), \"r\"(v) : \"memory\");
