  const unsigned rank = crank();
  for (int i = threadIdx.x; i < 64; i += kT) counter[i] = 0u;
  __syncthreads();
  carrive(); cwait();

  // 1) remote red into rank 0
  if (celect()) red_remote(remap(&counter[0], 0), rank + 1u);
  carrive(); cwait();
  if (rank == 0 && threadIdx.x == 0) dbg[0] = counter[0];   // expect sum(1..16)=136

