    native::red_remote(dst + bucket * sizeof(unsigned), count);
\"\"\"
PUSH_NEW = \"\"\"    const unsigned count = hist[bucket];
    native::red_remote(dst + bucket * sizeof(unsigned), count);
\"\"\"
SWEEP = \"\"\"  {
    unsigned acc = 0;
    #pragma unroll 1
    for (int i = threadIdx.x; i < kCacheItems; i += kThreads) acc += ordered(sm.cache[i]);
    if (acc == 0xffffffffu) sm.hist[0] = acc;
