// Cluster Top-K selection for one FP32 row, spread over a CTA cluster that keeps
// the whole row resident in shared memory.
//
//   sweep A : global -> shared (float4) fused with the top radix histogram
//   [1]     : every CTA partial histogram is complete
//   combine : every CTA merges all partial histograms over DSMEM and solves the
//             crossing bucket itself, so no leader broadcast follows
//   sweep B : next radix field, kept only when the crossing bucket is still too
//             wide to gather
//   [2]     : ditto
//   combine : crossing sub-bucket
//   sweep C : classify; winners staged per CTA, candidates shipped to the
//             leader's gather buffer
//   [3]     : gather buffer and per-CTA tallies landed on the leader
//   emit    : owners fill their reserved winner interval, the leader refines the
//             candidates and fills the tail of the output
//
// Keys are "'`ordered` (lower is better), so every scan walks best to worst.
#pragma once

#include <cstdint>

#include "native.cuh"

namespace topk {

constexpr int kLength = 131072;
constexpr int kSelected = 2048;

constexpr int kThreads = 512;
constexpr int kBlocks = 16;
constexpr int kWarps = kThreads / 32;

constexpr int kChunkItems = 4096;
constexpr int kChunksPerCta = kLength / (kBlocks * kChunkItems);
constexpr int kCacheItems = kChunksPerCta * kChunkItems;
