// ===== block scan ===========================================================

// Inclusive-free prefix over one value per thread; callers must be uniform.
__device__ __forceinline__ unsigned block_scan(Shared& sm, unsigned value) {
  unsigned incl = value;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1) incl = native::scan_step(incl, offset);

  const int warp = threadIdx.x >> 5;
  if ((threadIdx.x & 31) == 31) sm.warp_totals[warp] = incl;
  __syncthreads();

  if (threadIdx.x == 0) {
    unsigned run = 0;
    #pragma unroll
    for (int w = 0; w < kWarps; ++w) {
      const unsigned total = sm.warp_totals[w];
      sm.warp_base[w] = run;
      run += total;
    }
