// ===== sweep A: load and top histogram ======================================

__device__ __forceinline__ void load_hist(Shared& sm, const float* input, unsigned rank) {
  const float4* src = reinterpret_cast<const float4*>(input) + rank * kChunkVecs;
  float4* dst = reinterpret_cast<float4*>(sm.cache);

  // Issue all loads first so their latencies overlap.
  float4 vec[kVecsPerThread];
  #pragma unroll
  for (int m = 0; m < kVecsPerThread; ++m) {
    const int v = threadIdx.x + m * kThreads;
    vec[m] = src[(v >> 10) * (kBlocks * kChunkVecs) + (v & (kChunkVecs - 1))];
  }

  #pragma unroll
  for (int m = 0; m < kVecsPerThread; ++m) {
    const int v = threadIdx.x + m * kThreads;
    dst[v] = vec[m];
    #pragma unroll
    for (int j = 0; j < 4; ++j) {
      const unsigned key = ordered(comp(vec[m], j));
      native::red_shared(&sm.top[key >> kTopShift]);
