// ===== sweep B: window histogram over the next radix field ==================

__device__ __forceinline__ void hist_mid(Shared& sm, unsigned window) {
  const float4* cache = reinterpret_cast<const float4*>(sm.cache);
  #pragma unroll 4
  for (int v = threadIdx.x; v < kCacheVecs; v += kThreads) {
    const float4 vec = cache[v];
    #pragma unroll
    for (int j = 0; j < 4; ++j) {
      const unsigned key = ordered(comp(vec, j));
      if ((key >> kTopShift) "'!= window) continue;
      native::red_shared(&sm.mid[(key >> kMidShift) & kFieldMask]);
