// the bucket that holds the "'`need`-th key of the window.
__device__ __forceinline__ void choose(Shared& sm, const unsigned* hist,
    unsigned buckets, unsigned need) {
  const int tid = threadIdx.x;
  unsigned total = 0;
  if (tid < static_cast<int>(buckets)) {
    #pragma unroll
    for (int r = 0; r < kBlocks; ++r)
      total += native::load_remote(native::remote(&hist[tid], r));
  }

  const unsigned running = block_scan(sm, total);
  if (tid < static_cast<int>(buckets) && running < need && running + total >= need) {
    sm.crossing[0] = static_cast<unsigned>(tid);
    sm.crossing[1] = running;
    sm.crossing[2] = total;
