// ===== sweep C: classify the window =========================================

__device__ __forceinline__ void classify(Shared& sm, unsigned rank, unsigned pfx, int shift) {
  const float4* cache = reinterpret_cast<const float4*>(sm.cache);
  unsigned* win = &sm.win_cursor;
