  unsigned base = 0;
  #pragma unroll
  for (int r = 0; r < kBlocks; ++r) base += (static_cast<unsigned>(r) < rank) ? counts[r] : 0u;

  const unsigned staged = sm.win_cursor;
  #pragma unroll 1
  for (unsigned j = threadIdx.x; j < staged; j += kThreads) {
    const unsigned slot = sm.stage[j];
    values[base + j] = sm.cache[slot];
