    unsigned run = 0;
    #pragma unroll
    for (int r = 0; r < kBlocks; ++r) {
      const unsigned count = native::load_remote(native::remote(&sm.tally[kBlocks + r], 0));
      sm.region_cnt[r] = count;
      sm.region_base[r] = run;
      run += count;
    }
    sm.cand_total = run;
  }
  __syncthreads();

  #pragma unroll 1
  for (int r = 0; r < kBlocks; ++r) {
    const unsigned count = sm.region_cnt[r];
    const unsigned base = sm.region_base[r];
    const unsigned* region = sm.cand + r * kCandRegion;
    for (unsigned j = tid; j < count; j += kThreads) {
      const unsigned g = global_index(static_cast<unsigned>(r), region[j]);
      const float value = input[g];
      sm.ckey[base + j] = ordered(value);
      sm.cidx[base + j] = g;
      sm.cval[base + j] = value;
