// Resolve the low key bits of the gathered candidates, best first.
__device__ __forceinline__ void refine(Shared& sm, unsigned need, float* values,
    int64_t* indices) {
  const int tid = threadIdx.x;
  const unsigned count = sm.cand_total;

  unsigned plo = kMidShift;             // unresolved low bits of the window
  unsigned pw = sm.ckey[0] >> kMidShift;
  unsigned flo = 0;
  unsigned fmsk = 0;
  unsigned fb = 0;
  unsigned need_r = need;

  while (need_r < count) {
    if (plo == 0) break;                // all window keys are identical
    const unsigned width = plo < kRefineBits ? plo : kRefineBits;
    const unsigned llo = plo - width;
    const unsigned buckets = 1u << width;
    const unsigned mask = buckets - 1u;

    for (unsigned i = tid; i < buckets; i += kThreads) sm.level[i] = 0u;
    __syncthreads();

    #pragma unroll 1
    for (unsigned j = tid; j < count; j += kThreads) {
      const unsigned key = sm.ckey[j];
      if ((key >> plo) != pw) continue;
      native::red_shared(&sm.level[(key >> llo) & mask]);
    }
    __syncthreads();

    const unsigned total = tid < static_cast<int>(buckets) ? sm.level[tid] : 0u;
    const unsigned running = block_scan(sm, total);
    if (tid < static_cast<int>(buckets) && running < need_r && running + total >= need_r) {
      sm.crossing[0] = static_cast<unsigned>(tid);
      sm.crossing[1] = running;
      sm.crossing[2] = total;
    }
    __syncthreads();

    const unsigned bucket = sm.crossing[0];
    const unsigned above = sm.crossing[1];
    const unsigned held = sm.crossing[2];
    if (held == need_r - above) {       // the bucket exactly fills the request
      flo = llo;
      fmsk = mask;
      fb = bucket;
      break;
    }
    pw = (pw << width) | bucket;
    plo = llo;
    need_r -= above;
  }

  emit_cands(sm, plo, pw, flo, fmsk, fb, need_r, values, indices);
}

// ===== kernel ===============================================================

__global__ void __launch_bounds__(kThreads, 1) select(const float* __restrict__ input,
    float* __restrict__ values, int64_t* __restrict__ indices) {
  __shared__ Shared sm;
  const unsigned rank = native::rank();
  const int tid = threadIdx.x;

  if (tid == 0) {
    sm.win_cursor = 0u;
    sm.cand_cursor = 0u;
  }
  #pragma unroll 1
  for (int i = tid; i < kFieldBuckets; i += kThreads) sm.top[i] = 0u;
  __syncthreads();

  // Sweep A: one global pass fills the cache and the top-level histogram.
  load_hist(sm, input, rank);
  __syncthreads();
  native::sync();

  choose(sm, sm.top, kFieldBuckets, kSelected);
  unsigned above = sm.crossing[1];
  unsigned need = kSelected - above;
  unsigned pfx = sm.crossing[0];
  unsigned held = sm.crossing[2];
  unsigned shift = kTopShift;
  __syncthreads();

  if (held > kCandRegion) {
    for (int i = tid; i < kFieldBuckets; i += kThreads) sm.mid[i] = 0u;
    __syncthreads();
    hist_mid(sm, pfx);
    __syncthreads();
    native::sync();

    choose(sm, sm.mid, kFieldBuckets, need);
    above += sm.crossing[1];
    need -= sm.crossing[1];
    pfx = (pfx << kFieldBits) | sm.crossing[0];
    shift = kMidShift;
    __syncthreads();
  }

  // Sweep C: stage winners, ship the candidates to the leader.
  classify(sm, rank, pfx, shift);
  __syncthreads();
  if (native::elect()) {
    const unsigned st = native::remote(&sm.tally[rank], 0);
    native::store_remote(st, sm.win_cursor);
    native::store_remote(st + sizeof(unsigned), sm.cand_cursor);
  }
  native::sync();

  emit_winners(sm, rank, values, indices);

  if (rank == 0) {
    gather_cands(sm, input);
    refine(sm, need, values, indices);
  }
}

