  1	// Cluster Top-K selection for one FP32 row, spread over a CTA cluster that keeps
  2	// the whole row resident in shared memory.
  3	//
  4	//   sweep A : global -> shared (float4) fused with the top radix histogram
  5	//   [1]     : every CTA partial histogram is complete
  6	//   combine : every CTA merges all partial histograms over DSMEM and solves the
  7	//             crossing bucket itself, so no leader broadcast follows
  8	//   sweep B : next radix field, kept only when the crossing bucket is still too
  9	//             wide to gather
 10	//   [2]     : ditto
 11	//   combine : crossing sub-bucket
 12	//   sweep C : classify; winners staged per CTA, candidates shipped to the
 13	//             leader's gather buffer
 14	//   [3]     : gather buffer and per-CTA tallies landed on the leader
 15	//   emit    : owners fill their reserved winner interval, the leader refines the
 16	//             candidates and fills the tail of the output
 17	//
 18	// Keys are `ordered` (lower is better), so every scan walks best to worst.
 19	#pragma once
 20	
 21	#include <cstdint>
 22	
 23	#include "native.cuh"
 24	
 25	namespace topk {
 26	
 27	constexpr int kLength = 131072;
 28	constexpr int kSelected = 2048;
 29	
 30	constexpr int kThreads = 512;
 31	constexpr int kBlocks = 16;
 32	constexpr int kWarps = kThreads / 32;
 33	
 34	constexpr int kChunkItems = 4096;
 35	constexpr int kChunksPerCta = kLength / (kBlocks * kChunkItems);
 36	constexpr int kCacheItems = kChunksPerCta * kChunkItems;
 37	constexpr int kCacheVecs = kCacheItems / 4;
 38	constexpr int kChunkVecs = kChunkItems / 4;
 39	constexpr int kVecsPerThread = kCacheVecs / kThreads;
 40	
 41	constexpr int kKeyBits = 32;
 42	
 43	// Two 9-bit radix windows, [23, 32) then [14, 23); the surviving 14 low bits are
 44	// resolved on the leader. 512 buckets keep the DSMEM all-merge cheap.
 45	constexpr int kFieldBits = 9;
 46	constexpr int kFieldBuckets = 1 << kFieldBits;
 47	constexpr int kFieldMask = kFieldBuckets - 1;
 48	constexpr int kTopShift = 23;
 49	constexpr int kPasses = 4;             // top field plus three narrowing fields
 50	
 51	// Candidate slots reserved for one CTA inside the leader's gather buffer.
 52	constexpr int kCandRegion = 384;
 53	constexpr int kCandSlots = kBlocks * kCandRegion;
 54	
 55	// Leader-side refinement of the remaining low bits, kRefineBits at a time.
 56	constexpr int kRefineBits = 7;
 57	constexpr int kRefineBuckets = 1 << kRefineBits;
 58	
 59	static_assert(kCacheItems * kBlocks == kLength);
 60	static_assert(kCacheVecs % kThreads == 0);
 61	static_assert(kCandRegion <= kSelected);
 62	static_assert(kRefineBits < kKeyBits);
 63	
 64	struct alignas(16) Shared {
 65	  unsigned top[kFieldBuckets];          // per CTA, read cluster-wide
 66	  unsigned mid[kFieldBuckets];          // per CTA, read cluster-wide
 67	  unsigned tally[2 * kBlocks];          // leader: per-CTA winner/candidate counts
 68	  unsigned warp_totals[kWarps];
 69	  unsigned warp_base[kWarps];
 70	  unsigned crossing[4];                 // bucket, running, count, best
 71	  unsigned win_cursor;
 72	  unsigned cand_cursor;
 73	  unsigned region_cnt[kBlocks];
 74	  unsigned region_base[kBlocks];
 75	  unsigned cand_total;
 76	  unsigned emit;
 77	  unsigned stage[kSelected];            // staged winner cache slots
 78	  unsigned cand[kCandSlots];            // leader: candidate cache slots
 79	  unsigned ckey[kCandRegion];           // leader: dense candidate keys
 80	  unsigned cidx[kCandRegion];           // leader: dense candidate indices
 81	  float cval[kCandRegion];              // leader: dense candidate values
