 86	// Order-preserving FP32 -> u32 map, inverted so larger values get smaller keys.
 87	__device__ __forceinline__ unsigned ordered(float value) {
 88	  const unsigned bits = __float_as_uint(value);
 89	  const unsigned monotone =
 90	      bits ^ (static_cast<unsigned>(static_cast<int>(bits) >> 31) | 0x80000000u);
 91	  return ~monotone;
 92	}
 93	
 94	__device__ __forceinline__ float comp(const float4& vec, int j) {
 95	  return j == 0 ? vec.x : j == 1 ? vec.y : j == 2 ? vec.z : vec.w;
 96	}
 97	
 98	// Cache slot -> index in the caller's input row.
 99	__device__ __forceinline__ unsigned global_index(unsigned rank, unsigned slot) {
100	  return (rank + (slot >> 12) * kBlocks) * kChunkItems + (slot & (kChunkItems - 1));
101	}
102	
103	// ===== block scan ===========================================================
104	
105	// Inclusive-free prefix over one value per thread; callers must be uniform.
106	__device__ __forceinline__ unsigned block_scan(Shared& sm, unsigned value) {
107	  unsigned incl = value;
108	  #pragma unroll
109	  for (int offset = 1; offset < 32; offset <<= 1) incl = native::scan_step(incl, offset);
110	
111	  const int warp = threadIdx.x >> 5;
112	  if ((threadIdx.x & 31) == 31) sm.warp_totals[warp] = incl;
113	  __syncthreads();
114	
115	  if (threadIdx.x == 0) {
116	    unsigned run = 0;
117	    #pragma unroll
118	    for (int w = 0; w < kWarps; ++w) {
119	      const unsigned total = sm.warp_totals[w];
120	      sm.warp_base[w] = run;
121	      run += total;
122	    }
123	  }
124	  __syncthreads();
125	
126	  return sm.warp_base[warp] + (incl - value);
127	}
