129	// ===== sweep A: load and top histogram ======================================
130	
131	__device__ __forceinline__ void load_hist(Shared& sm, const float* input, unsigned rank) {
132	  const float4* src = reinterpret_cast<const float4*>(input) + rank * kChunkVecs;
133	  float4* dst = reinterpret_cast<float4*>(sm.cache);
134	
135	  // Issue all loads first so their latencies overlap.
136	  float4 vec[kVecsPerThread];
137	  #pragma unroll
138	  for (int m = 0; m < kVecsPerThread; ++m) {
139	    const int v = threadIdx.x + m * kThreads;
140	    vec[m] = src[(v >> 10) * (kBlocks * kChunkVecs) + (v & (kChunkVecs - 1))];
141	  }
142	
143	  #pragma unroll
144	  for (int m = 0; m < kVecsPerThread; ++m) {
145	    const int v = threadIdx.x + m * kThreads;
146	    dst[v] = vec[m];
147	    #pragma unroll
148	    for (int j = 0; j < 4; ++j) {
149	      const unsigned key = ordered(comp(vec[m], j));
150	      native::red_shared(&sm.top[key >> kTopShift]);
151	    }
152	  }
153	}
