155	// ===== sweep B: window histogram over the next radix field ==================
156	
157	// Histogram the radix field [shift - width, shift) of the keys that match the
158	// resolved prefix `window`.
159	__device__ __forceinline__ void hist_mid(Shared& sm, unsigned window, unsigned shift,
160	    unsigned width) {
161	  const float4* cache = reinterpret_cast<const float4*>(sm.cache);
162	  const unsigned lo = shift - width;
163	  const unsigned mask = (1u << width) - 1u;
164	  #pragma unroll 4
165	  for (int v = threadIdx.x; v < kCacheVecs; v += kThreads) {
166	    const float4 vec = cache[v];
167	    #pragma unroll
168	    for (int j = 0; j < 4; ++j) {
169	      const unsigned key = ordered(comp(vec, j));
170	      if ((key >> shift) != window) continue;
171	      native::red_shared(&sm.mid[(key >> lo) & mask]);
172	    }
173	  }
174	}
