176	// ===== combine ==============================================================
177	
178	// Merge the partial histogram of every CTA at this thread's own bucket and find
179	// the bucket that holds the `need`-th key of the window.
180	__device__ __forceinline__ void choose(Shared& sm, const unsigned* hist,
181	    unsigned buckets, unsigned need) {
182	  const int tid = threadIdx.x;
183	  unsigned total = 0;
184	  if (tid < static_cast<int>(buckets)) {
185	    #pragma unroll
186	    for (int r = 0; r < kBlocks; ++r)
187	      total += native::load_remote(native::remote(&hist[tid], r));
188	  }
189	
190	  const unsigned running = block_scan(sm, total);
191	  if (tid < static_cast<int>(buckets) && running < need && running + total >= need) {
192	    sm.crossing[0] = static_cast<unsigned>(tid);
193	    sm.crossing[1] = running;
194	    sm.crossing[2] = total;
195	  }
196	  __syncthreads();
197	}
