199	// ===== sweep C: classify the window =========================================
200	
201	__device__ __forceinline__ void classify(Shared& sm, unsigned rank, unsigned pfx,
202	    unsigned shift) {
203	  const float4* cache = reinterpret_cast<const float4*>(sm.cache);
204	  unsigned* win = &sm.win_cursor;
205	  unsigned* cand = &sm.cand_cursor;
206	  unsigned* region = sm.cand + rank * kCandRegion;
207	
208	  #pragma unroll 4
209	  for (int v = threadIdx.x; v < kCacheVecs; v += kThreads) {
210	    const float4 vec = cache[v];
211	    #pragma unroll
212	    for (int j = 0; j < 4; ++j) {
213	      const unsigned key = ordered(comp(vec, j));
214	      const unsigned top = key >> shift;
215	      if (top > pfx) continue;
216	      const unsigned slot = static_cast<unsigned>(v) * 4u + static_cast<unsigned>(j);
217	      if (top == pfx) {
218	        const unsigned at = native::add_shared(cand, 1u);
219	        if (at < kCandRegion) native::store_remote(native::remote(&region[at], 0), slot);
220	      } else {
221	        sm.stage[native::add_shared(win, 1u)] = slot;
222	      }
223	    }
224	  }
225	}
