227	// ===== emission =============================================================
228	
229	// Winner intervals are disjoint: rank r owns
230	// [sum of the lower ranks' counts, + its own count).
231	__device__ __forceinline__ void emit_winners(Shared& sm, unsigned rank,
232	    float* values, int64_t* indices) {
233	  unsigned counts[kBlocks];
234	  #pragma unroll
235	  for (int r = 0; r < kBlocks; ++r)
236	    counts[r] = native::load_remote(native::remote(&sm.tally[r], 0));
237	
238	  unsigned base = 0;
239	  #pragma unroll
240	  for (int r = 0; r < kBlocks; ++r) base += (static_cast<unsigned>(r) < rank) ? counts[r] : 0u;
241	
242	  const unsigned staged = sm.win_cursor;
243	  #pragma unroll 1
244	  for (unsigned j = threadIdx.x; j < staged; j += kThreads) {
245	    const unsigned slot = sm.stage[j];
246	    values[base + j] = sm.cache[slot];
247	    indices[base + j] = static_cast<int64_t>(global_index(rank, slot));
248	  }
249	}
