251	// Pack the per-CTA candidate regions into dense leader arrays.
252	__device__ __forceinline__ void gather_cands(Shared& sm, const float* input) {
253	  const int tid = threadIdx.x;
254	  if (tid == 0) {
255	    unsigned run = 0;
256	    #pragma unroll
257	    for (int r = 0; r < kBlocks; ++r) {
258	      const unsigned count = native::load_remote(native::remote(&sm.tally[kBlocks + r], 0));
259	      sm.region_cnt[r] = count;
260	      sm.region_base[r] = run;
261	      run += count;
262	    }
263	    sm.cand_total = run;
264	  }
265	  __syncthreads();
266	
267	  #pragma unroll 1
268	  for (int r = 0; r < kBlocks; ++r) {
269	    const unsigned count = sm.region_cnt[r];
270	    const unsigned base = sm.region_base[r];
271	    const unsigned* region = sm.cand + r * kCandRegion;
272	    for (unsigned j = tid; j < count; j += kThreads) {
273	      const unsigned g = global_index(static_cast<unsigned>(r), region[j]);
274	      const float value = input[g];
275	      sm.ckey[base + j] = ordered(value);
276	      sm.cidx[base + j] = g;
277	      sm.cval[base + j] = value;
278	    }
279	  }
280	  __syncthreads();
281	}
