283	// Write the `need_r` best window candidates into the tail of the output. A zero
284	// field mask selects every window key, which terminates the refinement.
285	__device__ __forceinline__ void emit_cands(Shared& sm, unsigned plo, unsigned pw,
286	    unsigned flo, unsigned fmsk, unsigned fb, unsigned need_r,
287	    float* values, int64_t* indices) {
288	  const int tid = threadIdx.x;
289	  if (tid == 0) sm.emit = kSelected - need_r;
290	  __syncthreads();
291	
292	  const unsigned count = sm.cand_total;
293	  #pragma unroll 1
294	  for (unsigned j = tid; j < count; j += kThreads) {
295	    const unsigned key = sm.ckey[j];
296	    if ((key >> plo) != pw) continue;
297	    if (((key >> flo) & fmsk) > fb) continue;
298	    const unsigned slot = native::add_shared(&sm.emit, 1u);
299	    if (slot >= kSelected) continue;
300	    values[slot] = sm.cval[j];
301	    indices[slot] = static_cast<int64_t>(sm.cidx[j]);
302	  }
303	}
304	
305	// Resolve the low key bits of the gathered candidates, best first.
306	__device__ __forceinline__ void refine(Shared& sm, unsigned shift, unsigned pfx,
307	    unsigned need, float* values, int64_t* indices) {
308	  const int tid = threadIdx.x;
309	  const unsigned count = sm.cand_total;
310	
311	  unsigned plo = shift;                 // unresolved low bits of the window
312	  unsigned pw = pfx;
