// Radix Top-K selection for one [1, S] FP32 score row, distributed over an
// SM90 CTA cluster that keeps the whole row resident in shared memory.
//
// Layout of the algorithm
// -----------------------
//   sweep A : global -> shared cache (float4), then the 9-bit top histogram
//   merge   : remote "'`red` of each CTA histogram into rank 0'"'s accumulator
//   choose  : every CTA block-scans rank 0's accumulator, so the crossing
//             bucket reaches all CTAs without a second cluster barrier
//   sweep B : prefix-filtered histogram of the next 9 bits
//   sweep C : third 9-bit field
//   sweep D : last 5 bits, which completes the key
//   emit    : reserve one interval per output region in rank 0, then write
//
// Nine-bit fields keep each partial histogram at 512 buckets so the DSMEM merge
// stays small; four fields tile the key exactly, so the surviving window is
// always key-exact. "'`splitter` is the accumulated key prefix; lower encodings
// are better, so every scan walks best to worst.
#pragma once

#include <cstdint>

#include "native.cuh"

namespace topk {

constexpr int kLength = 131072;
constexpr int kSelected = 2048;

constexpr int kThreads = 512;
constexpr int kBlocks = 16;
constexpr int kWarps = kThreads / 32;

constexpr int kChunkItems = 4096;
constexpr int kChunksPerCta = kLength / (kBlocks * kChunkItems);
constexpr int kCacheItems = kChunksPerCta * kChunkItems;

constexpr int kKeyBits = 32;
constexpr int kPasses = 4;
constexpr int kMaxBuckets = 1 << 9;

// Radix digit window per pass: bits [bit, bit + width).
constexpr int kPassBit[kPasses] = {23, 14, 5, 0};
constexpr int kPassWidth[kPasses] = {9, 9, 9, 5};

static_assert(kBlocks % 2 == 0);
static_assert(kCacheItems * kBlocks == kLength);
static_assert(kMaxBuckets <= kThreads);
static_assert(kPassBit[0] + kPassWidth[0] == kKeyBits);
static_assert(kPassBit[1] + kPassWidth[1] == kPassBit[0]);
static_assert(kPassBit[2] + kPassWidth[2] == kPassBit[1]);
static_assert(kPassBit[3] + kPassWidth[3] == kPassBit[2]);
static_assert(kPassBit[3] == 0);

// Order-preserving FP32 -> u32 map, inverted so that larger scores get smaller
// keys: the cumulative bucket scan then walks best-to-worst from bucket zero.
__device__ __forceinline__ unsigned ordered(float value) {
  const unsigned bits = __float_as_uint(value);
  const unsigned monotone =
      bits ''^ (static_cast<unsigned>(static_cast<int>(bits) >> 31) | 0x80000000u);
  return ~monotone;
}

struct State {
  unsigned bucket;
  unsigned above;
  unsigned need;
  unsigned stop;
};

struct alignas(16) Shared {
  unsigned hist[kPasses * kMaxBuckets];
  unsigned merge[kPasses * kMaxBuckets];  // rank 0: cluster-wide histograms
  State state;
  unsigned win_res;                       // rank 0: winner slot cursor
  unsigned tie_res;                       // rank 0: tie slot cursor
  unsigned selected;                      // this CTA: winner slot base
  unsigned tied;                          // this CTA: tie slot base
  unsigned warp_totals[2 * kWarps];       // [0,W) warp totals, [W,2W) warp bases
  alignas(16) float cache[kCacheItems];
};

// ===== block scan ===========================================================

// Exclusive prefix over one value per thread; callers must be uniform.
__device__ __forceinline__ unsigned block_scan(Shared& sm, unsigned value) {
  unsigned incl = value;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1)
    incl = native::scan_step(incl, offset);

  const int warp = threadIdx.x >> 5;
  if ((threadIdx.x & 31) == 31) sm.warp_totals[warp] = incl;
  __syncthreads();

  if (threadIdx.x == 0) {
    unsigned run = 0;
    #pragma unroll
    for (int w = 0; w < kWarps; ++w) {
      sm.warp_totals[kWarps + w] = run;
      run += sm.warp_totals[w];
    }
  }
  __syncthreads();

  return sm.warp_totals[kWarps + warp] + (incl - value);
}

// ===== shared histogram =====================================================

template <int Pass>
__device__ __forceinline__ void histogram(Shared& sm, unsigned splitter) {
  unsigned* hist = sm.hist + Pass * kMaxBuckets;
  constexpr int kBit = kPassBit[Pass];
  constexpr unsigned kMask = (1u << kPassWidth[Pass]) - 1u;
  constexpr int kPriorBit = kPassBit[Pass == 0 ? 0 : Pass - 1];

  #pragma unroll 1
  for (int i = threadIdx.x; i < kCacheItems; i += kThreads) {
    const unsigned key = ordered(sm.cache[i]);
    if (Pass != 0 && ((key >> kPriorBit) << kPriorBit) != splitter) continue;
    native::red_shared(hist + ((key >> kBit) & kMask));
  }
}

// Every CTA runs the prefix over rank 0'"'s merged histogram, so the crossing
// bucket is known cluster-wide as soon as the merge is visible.
template <int Pass>
__device__ __forceinline__ void choose(Shared& sm) {
  constexpr unsigned kBuckets = 1u << kPassWidth[Pass];
  const int tid = threadIdx.x;
  const unsigned base = native::remote(sm.merge + Pass * kMaxBuckets, 0);

  const unsigned total = static_cast<unsigned>(tid) < kBuckets
      ? native::load_remote(base + tid * sizeof(unsigned)) : 0u;
  const unsigned running = block_scan(sm, total);

  const unsigned need = sm.state.need;
  if (static_cast<unsigned>(tid) < kBuckets && running < need && running + total >= need) {
    sm.state.bucket = static_cast<unsigned>(tid);
    sm.state.above += running;
    sm.state.need = need - running;
    sm.state.stop = (total == need - running) ? 1u : 0u;
  }
  __syncthreads();
}

// ===== one radix pass =======================================================

template <int Pass>
__device__ __forceinline__ void run_pass(Shared& sm, unsigned& splitter,
    int& final_bit, bool& stop) {
  constexpr int kBit = kPassBit[Pass];
  constexpr unsigned kBuckets = 1u << kPassWidth[Pass];

  histogram<Pass>(sm, splitter);
  __syncthreads();                      // local histogram complete (CTA-only)

  // Push this CTA's counts into rank 0's accumulator; later passes are sparse.
  const unsigned dst = native::remote(sm.merge + Pass * kMaxBuckets, 0);
  const unsigned* hist = sm.hist + Pass * kMaxBuckets;
  if (static_cast<unsigned>(threadIdx.x) < kBuckets) {
    const unsigned count = hist[threadIdx.x];
    if (count "'!= 0) native::red_remote(dst + threadIdx.x * sizeof(unsigned), count);
  }
  native::sync();                       // merged histogram complete

  choose<Pass>(sm);
  stop = sm.state.stop != 0;
  splitter |= sm.state.bucket << kBit;
  final_bit = kBit;
}

// ===== emission =============================================================

__device__ __forceinline__ void block_sum2(Shared& sm, unsigned& first, unsigned& second) {
  const int tid = threadIdx.x;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    first += __shfl_down_sync(native::kWarpMask, first, offset);
    second += __shfl_down_sync(native::kWarpMask, second, offset);
  }
  if ((tid % 32) == 0) {
    sm.warp_totals[tid / 32] = first;
    sm.warp_totals[kWarps + tid / 32] = second;
  }
  __syncthreads();
  if (tid == 0) {
    unsigned a = 0;
    unsigned b = 0;
    #pragma unroll
    for (int warp = 0; warp < kWarps; ++warp) {
      a += sm.warp_totals[warp];
      b += sm.warp_totals[kWarps + warp];
    }
    sm.warp_totals[0] = a;
    sm.warp_totals[kWarps] = b;
  }
  __syncthreads();
  first = sm.warp_totals[0];
  second = sm.warp_totals[kWarps];
}

__device__ __forceinline__ void emit(Shared& sm, unsigned rank, unsigned splitter,
    int final_bit, float* values, int64_t* indices) {
  const int tid = threadIdx.x;

  unsigned strict = 0;
  unsigned ties = 0;
  #pragma unroll 1
  for (int i = tid; i < kCacheItems; i += kThreads) {
    const unsigned key = (ordered(sm.cache[i]) >> final_bit) << final_bit;
    strict += key < splitter ? 1u : 0u;
    ties += key == splitter ? 1u : 0u;
  }
  block_sum2(sm, strict, ties);

  // Reserve one contiguous interval per output region. Rank 0'"'s cursors make
  // the intervals disjoint without a barrier; the tie interval starts after the
  // strict winners, whose cluster-wide total "'`choose` already resolved.
  if (native::elect()) {
    sm.selected = native::atom_add_remote(native::remote(&sm.win_res, 0), strict);
    sm.tied = sm.state.above + native::atom_add_remote(native::remote(&sm.tie_res, 0), ties);
  }
  __syncthreads();

  #pragma unroll 1
  for (int i = tid; i < kCacheItems; i += kThreads) {
    const float value = sm.cache[i];
    const unsigned key = (ordered(value) >> final_bit) << final_bit;
    if (key > splitter) continue;

    // Unique slot per candidate; excess threshold ties fall past kSelected.
    const unsigned out = key == splitter ? atomicAdd(&sm.tied, 1u) : atomicAdd(&sm.selected, 1u);
    if (out >= kSelected) continue;

    values[out] = value;
    indices[out] = static_cast<int64_t>(rank + (i >> 12) * kBlocks) * kChunkItems
        + (i & (kChunkItems - 1));
  }
}

// ===== kernel ===============================================================

__device__ __forceinline__ void load_cache(Shared& sm, const float* input, unsigned rank) {
  constexpr int kVecPerChunk = kChunkItems / 4;
  #pragma unroll
  for (int chunk = 0; chunk < kChunksPerCta; ++chunk) {
