  const unsigned base = native::remote(sm.merge + Pass * kMaxBuckets, 0);

  const unsigned total = static_cast<unsigned>(tid) < kBuckets
      ? native::load_remote(base + tid * sizeof(unsigned)) : 0u;
  const unsigned running = block_scan(sm, total);

  const unsigned need = sm.state.need;
  if (static_cast<unsigned>(tid) < kBuckets && running < need && running + total >= need) {
    sm.state.bucket = static_cast<unsigned>(tid);
    sm.state.above += running;
    sm.state.need = need - running;
    sm.state.stop = (total == need - running) ? 1u : 0u;
  }
  __syncthreads();
}

// ===== one radix pass =======================================================

template <int Pass>
__device__ __forceinline__ void run_pass(Shared& sm, unsigned& splitter,
    int& final_bit, bool& stop) {
  constexpr int kBit = kPassBit[Pass];
  constexpr unsigned kBuckets = 1u << kPassWidth[Pass];

  histogram<Pass>(sm, splitter);
  __syncthreads();                      // local histogram complete (CTA-only)

  // Push this CTA's counts into rank 0's accumulator; later passes are sparse.
  const unsigned dst = native::remote(sm.merge + Pass * kMaxBuckets, 0);
  const unsigned* hist = sm.hist + Pass * kMaxBuckets;
  if (static_cast<unsigned>(threadIdx.x) < kBuckets) {
    const unsigned count = hist[threadIdx.x];
    if (count "'!= 0) native::red_remote(dst + threadIdx.x * sizeof(unsigned), count);
  }
  native::sync();                       // merged histogram complete

  choose<Pass>(sm);
  stop = sm.state.stop != 0;
  splitter |= sm.state.bucket << kBit;
  final_bit = kBit;
}

// ===== emission =============================================================

__device__ __forceinline__ void block_sum2(Shared& sm, unsigned& first, unsigned& second) {
  const int tid = threadIdx.x;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    first += __shfl_down_sync(native::kWarpMask, first, offset);
    second += __shfl_down_sync(native::kWarpMask, second, offset);
  }
  if ((tid % 32) == 0) {
    sm.warp_totals[tid / 32] = first;
    sm.warp_totals[kWarps + tid / 32] = second;
  }
  __syncthreads();
  if (tid == 0) {
    unsigned a = 0;
    unsigned b = 0;
    #pragma unroll
    for (int warp = 0; warp < kWarps; ++warp) {
      a += sm.warp_totals[warp];
      b += sm.warp_totals[kWarps + warp];
