  // the intervals disjoint without a barrier; the tie interval starts after the
  // strict winners, whose cluster-wide total "'`choose` already resolved.
  if (native::elect()) {
    sm.selected = native::atom_add_remote(native::remote(&sm.win_res, 0), strict);
    sm.tied = sm.state.above + native::atom_add_remote(native::remote(&sm.tie_res, 0), ties);
  }
  __syncthreads();

  #pragma unroll 1
  for (int i = tid; i < kCacheItems; i += kThreads) {
    const float value = sm.cache[i];
    const unsigned key = (ordered(value) >> final_bit) << final_bit;
    if (key > splitter) continue;

    // Unique slot per candidate; excess threshold ties fall past kSelected.
    const unsigned out = key == splitter ? atomicAdd(&sm.tied, 1u) : atomicAdd(&sm.selected, 1u);
    if (out >= kSelected) continue;

    values[out] = value;
    indices[out] = static_cast<int64_t>(rank + (i >> 12) * kBlocks) * kChunkItems
