  run_pass<0>(sm, splitter, final_bit, stop);
  if (!stop) run_pass<1>(sm, splitter, final_bit, stop);
  if (!stop) run_pass<2>(sm, splitter, final_bit, stop);
  if (!stop) run_pass<3>(sm, splitter, final_bit, stop);

