template <int Pass>
__device__ __forceinline__ void histogram(Shared& sm, unsigned window) {
  unsigned* hist = sm.hist + Pass * kFieldBuckets;
  constexpr int kBit = kPassShift[Pass];
  constexpr int kFilterShift = kPassShift[Pass == 0 ? 0 : Pass - 1];
  constexpr unsigned kMask = kPassBuckets[Pass] - 1u;

  #pragma unroll 1
  for (int i = threadIdx.x; i < kCacheItems; i += kThreads) {
    const unsigned key = ordered(sm.cache[i]);
    if (Pass != 0 && (key >> kFilterShift) != window) continue;
    native::red_shared(hist + ((key >> kBit) & kMask));
