// ===== emission =============================================================

__device__ __forceinline__ void write_out(Shared& sm, unsigned slot, unsigned value,
    unsigned index, float* values, int64_t* indices) {
  const unsigned out = native::add_shared(&sm.emit, 1u);
  if (out >= kSelected) return;
  values[out] = __uint_as_float(value);
  indices[out] = static_cast<int64_t>(index);
  (void)slot;
}

// Resolve the low bits of the gathered window: every bucket better than the
// crossing one is emitted outright, and the crossing bucket is compacted for
// the next round. Ends when the survivors are exactly what is still missing.
__device__ __forceinline__ void refine(Shared& sm, unsigned shift, unsigned need,
    float* values, int64_t* indices) {
  const int tid = threadIdx.x;
  unsigned n = sm.cand_total;
  unsigned need_r = need;
  unsigned lo = shift;

  if (tid == 0) sm.emit = sm.state.above;
  __syncthreads();

  // Degenerate window: a fully resolved key leaves identical survivors, so
  // repeating one of them is exact.
  if (n < need_r) {
    #pragma unroll 1
    for (unsigned j = tid; j < n; j += kThreads)
      write_out(sm, 0u, sm.cval[j], sm.cidx[j], values, indices);
    __syncthreads();
    for (unsigned j = tid; j < need_r - n; j += kThreads) {
      const unsigned out = native::add_shared(&sm.emit, 1u);
      if (out >= kSelected) continue;
      values[out] = __uint_as_float(sm.cval[0]);
      indices[out] = static_cast<int64_t>(sm.cidx[0]);
    }
    return;
  }

  while (n > need_r && lo > 0u) {
    const unsigned width = lo < kRefineBits ? lo : kRefineBits;
    const unsigned llo = lo - width;
    const unsigned mask = (1u << width) - 1u;
    const unsigned buckets = 1u << width;

    for (unsigned i = tid; i < buckets; i += kThreads) sm.level[i] = 0u;
    __syncthreads();

    #pragma unroll 1
    for (unsigned j = tid; j < n; j += kThreads)
      native::red_shared(&sm.level[(sm.ckey[j] >> llo) & mask]);
    __syncthreads();

    const unsigned total = static_cast<unsigned>(tid) < buckets ? sm.level[tid] : 0u;
    const unsigned running = block_scan(sm, total);
    if (static_cast<unsigned>(tid) < buckets && running < need_r && running + total >= need_r) {
      sm.crossing[0] = static_cast<unsigned>(tid);
      sm.crossing[1] = running;
      sm.crossing[2] = total;
    }
    __syncthreads();

    const unsigned bucket = sm.crossing[0];
    const unsigned above_r = sm.crossing[1];
    const unsigned held = sm.crossing[2];

    // Buckets before the crossing one are strictly better: emit them all.
    #pragma unroll 1
    for (unsigned j = tid; j < n; j += kThreads) {
      if (((sm.ckey[j] >> llo) & mask) >= bucket) continue;
      write_out(sm, 0u, sm.cval[j], sm.cidx[j], values, indices);
    }
    __syncthreads();

    // Compact the crossing bucket; only it can still contribute.
    if (tid == 0) sm.compact = 0u;
    __syncthreads();
    #pragma unroll 1
    for (unsigned j = tid; j < n; j += kThreads) {
      if (((sm.ckey[j] >> llo) & mask) != bucket) continue;
      const unsigned at = native::add_shared(&sm.compact, 1u);
      sm.ckey2[at] = sm.ckey[j];
      sm.cval2[at] = sm.cval[j];
      sm.cidx2[at] = sm.cidx[j];
    }
    __syncthreads();
    for (unsigned j = tid; j < held; j += kThreads) {
      sm.ckey[j] = sm.ckey2[j];
      sm.cval[j] = sm.cval2[j];
      sm.cidx[j] = sm.cidx2[j];
    }
    __syncthreads();

    n = held;
    need_r -= above_r;
    lo = llo;
  }

  #pragma unroll 1
  for (unsigned j = tid; j < n && j < need_r; j += kThreads)
    write_out(sm, 0u, sm.cval[j], sm.cidx[j], values, indices);
}

// rank 0: dense-pack the gathered cache slots into keys, values and indices.
__device__ __forceinline__ void gather(Shared& sm, const float* input) {
  const int tid = threadIdx.x;
  if (tid == 0) {
    unsigned run = 0;
    #pragma unroll
    for (int r = 0; r < kBlocks; ++r) {
      const unsigned count = sm.tally[2 * r + 1];
      sm.region_cnt[r] = count;
      sm.region_base[r] = run;
      run += count;
    }
    sm.cand_total = run;
  }
  __syncthreads();

  #pragma unroll 1
  for (int r = 0; r < kBlocks; ++r) {
    const unsigned count = sm.region_cnt[r];
    const unsigned base = sm.region_base[r];
    const unsigned* region = sm.cand + r * kCandRegion;
    #pragma unroll 1
    for (unsigned j = tid; j < count; j += kThreads) {
      const unsigned index = global_index(static_cast<unsigned>(r), region[j]);
      const float value = input[index];
      sm.ckey[base + j] = ordered(value);
      sm.cval[base + j] = __float_as_uint(value);
      sm.cidx[base + j] = index;
    }
  }
  __syncthreads();
}

// Count strict winners and window members, reserve a winner interval in rank 0,
// write the winners and ship the window slots; rank 0 then finishes the window.
__device__ __forceinline__ void emit_all(Shared& sm, unsigned rank, const float* input,
    unsigned pfx, unsigned shift, float* values, int64_t* indices) {
  const int tid = threadIdx.x;

  unsigned win = 0;
  unsigned cand = 0;
  #pragma unroll 1
  for (int i = tid; i < kCacheItems; i += kThreads) {
    const unsigned top = ordered(sm.cache[i]) >> shift;
    win += top < pfx ? 1u : 0u;
    cand += top == pfx ? 1u : 0u;
  }
  block_sum2(sm, win, cand);

  if (native::elect()) {
    sm.win_base = native::atom_add_remote(native::remote(&sm.win_res, 0), win);
    const unsigned slot = native::remote(&sm.tally[2 * rank], 0);
    native::store_remote(slot, win);
    native::store_remote(slot + sizeof(unsigned),
        cand < kCandRegion ? cand : static_cast<unsigned>(kCandRegion));
  }
  if (tid == 0) {
    sm.emit = 0u;
    sm.cand_cursor = 0u;
  }
  __syncthreads();

  // `state.above` already holds the cluster-wide winner count, so the reserved
  // interval [win_base, win_base + win) is exactly the winner region.
  unsigned* region = sm.cand + rank * kCandRegion;
  #pragma unroll 1
  for (int i = tid; i < kCacheItems; i += kThreads) {
    const unsigned top = ordered(sm.cache[i]) >> shift;
    if (top < pfx) {
      const unsigned at = native::add_shared(&sm.emit, 1u);
      values[sm.win_base + at] = sm.cache[i];
      indices[sm.win_base + at] = static_cast<int64_t>(global_index(rank, static_cast<unsigned>(i)));
      continue;
    }
    if (top > pfx) continue;

    const unsigned at = native::add_shared(&sm.cand_cursor, 1u);
    if (at < kCandRegion) native::store_remote(native::remote(&region[at], 0),
        static_cast<unsigned>(i));
  }
  __syncthreads();

  native::sync();                       // gathered window and tallies landed

  if (rank == 0) {
    gather(sm, input);
    refine(sm, shift, sm.state.need, values, indices);
  }
}

// ===== kernel ===============================================================

__device__ __forceinline__ void load_cache(Shared& sm, const float* input, unsigned rank) {
  constexpr int kVecPerChunk = kChunkItems / 4;
  #pragma unroll
  for (int chunk = 0; chunk < kChunksPerCta; ++chunk) {
    const float4* src = reinterpret_cast<const float4*>(
        input + (rank + chunk * kBlocks) * kChunkItems);
    float4* dst = reinterpret_cast<float4*>(sm.cache + chunk * kChunkItems);
    #pragma unroll 1
    for (int i = threadIdx.x; i < kVecPerChunk; i += kThreads) dst[i] = src[i];
  }
}

__global__ void __launch_bounds__(kThreads, 1) select(const float* __restrict__ input,
    float* __restrict__ values, int64_t* __restrict__ indices) {
  __shared__ Shared sm;
  const unsigned rank = native::rank();

  if (native::elect()) {
    sm.state = {0u, 0u, static_cast<unsigned>(kSelected), 0u, 0u};
    sm.win_res = 0u;
  }
  #pragma unroll 1
  for (int i = threadIdx.x; i < kMaxPasses * kFieldBuckets; i += kThreads) {
    sm.hist[i] = 0u;
    sm.merge[i] = 0u;
  }
  __syncthreads();

  // Split barrier: rank 0'"'s zeroed accumulators must be cluster-visible before
  // any remote "'`red` lands in them. The wait overlaps the input load.
  native::arrive();
  load_cache(sm, input, rank);
  __syncthreads();
  native::wait();

  unsigned pfx = 0u;
  unsigned held = kLength;

  step<0>(sm, rank, pfx, held);
  if (held > kCandRegion) step<1>(sm, rank, pfx, held);
  if (held > kCandRegion) step<2>(sm, rank, pfx, held);
  if (held > kCandRegion) step<3>(sm, rank, pfx, held);

  const unsigned shift = (held > kCandRegion) ? 0u : kPassShift[0];
  emit_all(sm, rank, input, pfx, shift, values, indices);
}

}  // namespace topk
