// Radix Top-K selection for one [1, S] FP32 score row, distributed over an
// SM90 CTA cluster that keeps the whole row resident in shared memory.
//
// Layout of the algorithm
// -----------------------
//   sweep A : global -> shared cache (float4), then the 9-bit top histogram
//   merge   : remote "'`red` of each CTA histogram into rank 0'"'s accumulator
//   choose  : rank 0 block-scans the accumulator and publishes the crossing
//   narrow  : repeat the sweep inside the surviving window until the window is
//             small enough to gather (twice for this workload)
//   reserve : rank 0's cursor hands every CTA a disjoint winner interval
//   gather  : rank 0 collects the surviving slot ids and reads their values
//   refine  : rank 0 resolves the leftover bits and fills the tie region
//
// 9-bit fields keep every partial histogram at 512 buckets, so the DSMEM merge
// stays small. "'`pfx` is the resolved key prefix and `shift` the number of low
// bits still unknown; lower keys are better, so every scan walks best to worst.
#pragma once

#include <cstdint>

#include "native.cuh"

namespace topk {

constexpr int kLength = 131072;
constexpr int kSelected = 2048;

constexpr int kThreads = 512;
constexpr int kBlocks = 16;
constexpr int kWarps = kThreads / 32;

constexpr int kChunkItems = 4096;
constexpr int kChunksPerCta = kLength / (kBlocks * kChunkItems);
constexpr int kCacheItems = kChunksPerCta * kChunkItems;

constexpr int kKeyBits = 32;
constexpr int kFieldBits = 9;
constexpr int kFieldBuckets = 1 << kFieldBits;
constexpr int kTopShift = kKeyBits - kFieldBits;   // first field sits at the top

// Radix field per pass: bits [kPassShift, previous shift). The last field ends
// at bit 0, so a full pass sequence leaves no unresolved key bits.
constexpr int kMaxPasses = 4;
constexpr int kPassShift[kMaxPasses] = {kTopShift, 14, 5, 0};
constexpr int kPassWidth[kMaxPasses] = {kFieldBits, 9, 9, 5};
constexpr int kPassBuckets[kMaxPasses] = {kFieldBuckets, 512, 512, 32};

// The window is narrow enough to gather once its key count drops to this.
constexpr int kCandRegion = 256;
constexpr int kCandSlots = kBlocks * kCandRegion;

// Rank 0 resolves the gathered window kRefineBits at a time.
constexpr int kRefineBits = 7;
constexpr int kRefineBuckets = 1 << kRefineBits;

static_assert(kBlocks % 2 == 0);
static_assert(kCacheItems * kBlocks == kLength);
static_assert(kPassBuckets[0] == kFieldBuckets);
static_assert(kPassShift[0] == kTopShift);
static_assert(kPassShift[kMaxPasses - 1] == 0);
static_assert(kPassBuckets[kMaxPasses - 1] <= kThreads);
static_assert(kRefineBuckets <= kThreads);

// Order-preserving FP32 -> u32 map, inverted so that larger scores get smaller
// keys: the cumulative bucket scan then walks best-to-worst from bucket zero.
__device__ __forceinline__ unsigned ordered(float value) {
  const unsigned bits = __float_as_uint(value);
  const unsigned monotone =
      bits ''^ (static_cast<unsigned>(static_cast<int>(bits) >> 31) | 0x80000000u);
  return ~monotone;
}

// Cache slot -> index in the caller'"'s input row.
__device__ __forceinline__ unsigned global_index(unsigned rank, unsigned slot) {
  return (rank + (slot >> 12) * kBlocks) * kChunkItems + (slot & (kChunkItems - 1));
}

struct State {
  unsigned bucket;   // bucket holding the need-th key of the last window
  unsigned above;    // cluster-wide count of keys better than the window
  unsigned need;     // how many of the window the output still needs
  unsigned stop;     // the crossing bucket exactly fills the request
  unsigned held;     // cluster-wide size of the crossing bucket
};

struct alignas(16) Shared {
  unsigned hist[kMaxPasses * kFieldBuckets];
  unsigned merge[kMaxPasses * kFieldBuckets];  // rank 0: cluster-wide histograms
  State state;
  unsigned crossing[4];                   // rank 0: bucket, running, count
  unsigned warp_totals[2 * kWarps];
  unsigned win_res;                       // rank 0: winner slot cursor
  unsigned tally[2 * kBlocks];            // rank 0: per-CTA (winner, window) counts
  unsigned region_cnt[kBlocks];
  unsigned region_base[kBlocks];
  unsigned cand_total;
  unsigned emit;                          // local: next winner / tie slot
  unsigned compact;                       // rank 0: compaction cursor
  unsigned cand_cursor;                   // local: next window slot
  unsigned win_base;
  unsigned cand[kCandSlots];              // rank 0: gathered cache slots
  unsigned ckey[kCandRegion];             // rank 0: dense window keys
  unsigned cval[kCandRegion];
  unsigned cidx[kCandRegion];
  unsigned ckey2[kCandRegion];
  unsigned cval2[kCandRegion];
  unsigned cidx2[kCandRegion];
  unsigned level[kRefineBuckets];         // rank 0: refinement histogram
  alignas(16) float cache[kCacheItems];
};

// ===== block scan ===========================================================

// Exclusive prefix over one value per thread; callers must be uniform.
__device__ __forceinline__ unsigned block_scan(Shared& sm, unsigned value) {
  unsigned incl = value;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1)
    incl = native::scan_step(incl, offset);

  const int warp = threadIdx.x >> 5;
  if ((threadIdx.x & 31) == 31) sm.warp_totals[warp] = incl;
  __syncthreads();

  if (threadIdx.x == 0) {
    unsigned run = 0;
    #pragma unroll
    for (int w = 0; w < kWarps; ++w) {
      sm.warp_totals[kWarps + w] = run;
      run += sm.warp_totals[w];
    }
  }
  __syncthreads();

  return sm.warp_totals[kWarps + warp] + (incl - value);
}

__device__ __forceinline__ void block_sum2(Shared& sm, unsigned& first, unsigned& second) {
  const int tid = threadIdx.x;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    first += __shfl_down_sync(native::kWarpMask, first, offset);
    second += __shfl_down_sync(native::kWarpMask, second, offset);
  }
  if ((tid % 32) == 0) {
    sm.warp_totals[tid / 32] = first;
    sm.warp_totals[kWarps + tid / 32] = second;
  }
  __syncthreads();
  if (tid == 0) {
    unsigned a = 0;
    unsigned b = 0;
    #pragma unroll
    for (int warp = 0; warp < kWarps; ++warp) {
      a += sm.warp_totals[warp];
      b += sm.warp_totals[kWarps + warp];
    }
    sm.warp_totals[0] = a;
    sm.warp_totals[kWarps] = b;
  }
  __syncthreads();
  first = sm.warp_totals[0];
  second = sm.warp_totals[kWarps];
}

// ===== radix sweeps =========================================================

// Histogram one field of every key that still matches the window. Runs over the
// resident cache, so the input is read from global exactly once per kernel.
template <int Pass>
__device__ __forceinline__ void histogram(Shared& sm, unsigned pfx) {
  unsigned* hist = sm.hist + Pass * kFieldBuckets;
  constexpr int kBit = kPassShift[Pass];
  constexpr int kFilterShift = kPassShift[Pass == 0 ? 0 : Pass - 1];
  constexpr unsigned kMask = kPassBuckets[Pass] - 1u;

  #pragma unroll 1
  for (int i = threadIdx.x; i < kCacheItems; i += kThreads) {
    const unsigned key = ordered(sm.cache[i]);
    if (Pass "'!= 0 && (key >> kFilterShift) != pfx) continue;
    native::red_shared(hist + ((key >> kBit) & kMask));
  }
}

// rank 0: prefix over the merged histogram and pick the bucket holding the
// need-th key of the window.
template <int Pass>
__device__ __forceinline__ void choose(Shared& sm) {
  constexpr unsigned kBuckets = kPassBuckets[Pass];
  const int tid = threadIdx.x;
  const unsigned need = sm.state.need;
  const unsigned hist = native::remote(sm.merge + Pass * kFieldBuckets, 0);

  const unsigned total = static_cast<unsigned>(tid) < kBuckets
      ? native::load_remote(hist + tid * sizeof(unsigned)) : 0u;
  const unsigned running = block_scan(sm, total);

  if (static_cast<unsigned>(tid) < kBuckets && running < need && running + total >= need) {
    sm.state.bucket = static_cast<unsigned>(tid);
    sm.state.above += running;
    sm.state.need = need - running;
    sm.state.stop = (total == need - running) ? 1u : 0u;
    sm.state.held = total;
  }
  __syncthreads();
}

// One radix field: histogram, merge into rank 0, pick the crossing bucket and
// publish the new window. Leaves `pfx` covering bits [shift, 32).
template <int Pass>
__device__ __forceinline__ void step(Shared& sm, unsigned rank, unsigned& pfx,
    unsigned& held) {
  constexpr unsigned kBuckets = kPassBuckets[Pass];

  histogram<Pass>(sm, pfx);
  __syncthreads();                      // local histogram complete (CTA-only)

  // Push this CTA'"'s counts into rank 0's accumulator; later passes are sparse.
  const unsigned dst = native::remote(sm.merge + Pass * kFieldBuckets, 0);
  const unsigned* hist = sm.hist + Pass * kFieldBuckets;
  if (static_cast<unsigned>(threadIdx.x) < kBuckets) {
    const unsigned count = hist[threadIdx.x];
    if (count "'!= 0) native::red_remote(dst + threadIdx.x * sizeof(unsigned), count);
  }
  native::sync();                       // merged histogram complete

  if (rank == 0) choose<Pass>(sm);
  native::sync();                       // threshold published

  // Every CTA reads the published window; rank 0 stays resident until the next
  // cluster barrier, which follows the pushes of the next pass.
  const unsigned base = native::remote(&sm.state, 0);
  const unsigned bucket = native::load_remote(base);
  held = native::load_remote(base + 4 * sizeof(unsigned));
  sm.crossing[2] = held;
  pfx = (Pass == 0) ? bucket : ((pfx << kPassWidth[Pass]) | bucket);
}

// ===== emission =============================================================

__device__ __forceinline__ void write_out(Shared& sm, unsigned slot, unsigned value,
    unsigned index, float* values, int64_t* indices) {
  const unsigned out = native::add_shared(&sm.emit, 1u);
  if (out >= kSelected) return;
  values[out] = __uint_as_float(value);
  indices[out] = static_cast<int64_t>(index);
  (void)slot;
}

// Resolve the low bits of the gathered window: every bucket better than the
// crossing one is emitted outright, and the crossing bucket is compacted for
// the next round. Ends when the survivors are exactly what is still missing.
__device__ __forceinline__ void refine(Shared& sm, unsigned shift, unsigned need,
    float* values, int64_t* indices) {
  const int tid = threadIdx.x;
  unsigned n = sm.cand_total;
  unsigned need_r = need;
  unsigned lo = shift;

  if (tid == 0) sm.emit = sm.state.above;
  __syncthreads();

  // Degenerate window: a fully resolved key leaves identical survivors, so
  // repeating one of them is exact.
  if (n < need_r) {
    #pragma unroll 1
    for (unsigned j = tid; j < n; j += kThreads)
      write_out(sm, 0u, sm.cval[j], sm.cidx[j], values, indices);
    __syncthreads();
    for (unsigned j = tid; j < need_r - n; j += kThreads) {
      const unsigned out = native::add_shared(&sm.emit, 1u);
      if (out >= kSelected) continue;
      values[out] = __uint_as_float(sm.cval[0]);
      indices[out] = static_cast<int64_t>(sm.cidx[0]);
    }
    return;
  }

  while (n > need_r && lo > 0u) {
    const unsigned width = lo < kRefineBits ? lo : kRefineBits;
    const unsigned llo = lo - width;
    const unsigned mask = (1u << width) - 1u;
    const unsigned buckets = 1u << width;

    for (unsigned i = tid; i < buckets; i += kThreads) sm.level[i] = 0u;
    __syncthreads();

    #pragma unroll 1
    for (unsigned j = tid; j < n; j += kThreads)
      native::red_shared(&sm.level[(sm.ckey[j] >> llo) & mask]);
    __syncthreads();

    const unsigned total = static_cast<unsigned>(tid) < buckets ? sm.level[tid] : 0u;
    const unsigned running = block_scan(sm, total);
    if (static_cast<unsigned>(tid) < buckets && running < need_r && running + total >= need_r) {
      sm.crossing[0] = static_cast<unsigned>(tid);
      sm.crossing[1] = running;
      sm.crossing[2] = total;
    }
    __syncthreads();

    const unsigned bucket = sm.crossing[0];
    const unsigned above_r = sm.crossing[1];
    const unsigned held = sm.crossing[2];

    // Buckets before the crossing one are strictly better: emit them all.
    #pragma unroll 1
    for (unsigned j = tid; j < n; j += kThreads) {
      if (((sm.ckey[j] >> llo) & mask) >= bucket) continue;
      write_out(sm, 0u, sm.cval[j], sm.cidx[j], values, indices);
    }
    __syncthreads();

    // Compact the crossing bucket; only it can still contribute.
    if (tid == 0) sm.compact = 0u;
    __syncthreads();
    #pragma unroll 1
    for (unsigned j = tid; j < n; j += kThreads) {
      if (((sm.ckey[j] >> llo) & mask) != bucket) continue;
      const unsigned at = native::add_shared(&sm.compact, 1u);
      sm.ckey2[at] = sm.ckey[j];
      sm.cval2[at] = sm.cval[j];
      sm.cidx2[at] = sm.cidx[j];
    }
    __syncthreads();
    for (unsigned j = tid; j < held; j += kThreads) {
      sm.ckey[j] = sm.ckey2[j];
      sm.cval[j] = sm.cval2[j];
      sm.cidx[j] = sm.cidx2[j];
    }
    __syncthreads();

    n = held;
    need_r -= above_r;
    lo = llo;
  }

  #pragma unroll 1
  for (unsigned j = tid; j < n && j < need_r; j += kThreads)
    write_out(sm, 0u, sm.cval[j], sm.cidx[j], values, indices);
}

// rank 0: dense-pack the gathered cache slots into keys, values and indices.
__device__ __forceinline__ void gather(Shared& sm, const float* input) {
  const int tid = threadIdx.x;
  if (tid == 0) {
    unsigned run = 0;
    #pragma unroll
    for (int r = 0; r < kBlocks; ++r) {
      const unsigned count = sm.tally[2 * r + 1];
      sm.region_cnt[r] = count;
      sm.region_base[r] = run;
      run += count;
    }
    sm.cand_total = run;
  }
  __syncthreads();

  #pragma unroll 1
  for (int r = 0; r < kBlocks; ++r) {
    const unsigned count = sm.region_cnt[r];
    const unsigned base = sm.region_base[r];
    const unsigned* region = sm.cand + r * kCandRegion;
    #pragma unroll 1
    for (unsigned j = tid; j < count; j += kThreads) {
      const unsigned index = global_index(static_cast<unsigned>(r), region[j]);
      const float value = input[index];
      sm.ckey[base + j] = ordered(value);
      sm.cval[base + j] = __float_as_uint(value);
      sm.cidx[base + j] = index;
    }
  }
  __syncthreads();
}

// Count strict winners and window members, reserve a winner interval in rank 0,
// write the winners and ship the window slots; rank 0 then finishes the window.
__device__ __forceinline__ void emit_all(Shared& sm, unsigned rank, const float* input,
    unsigned pfx, unsigned shift, float* values, int64_t* indices) {
  const int tid = threadIdx.x;

  unsigned win = 0;
  unsigned cand = 0;
  #pragma unroll 1
  for (int i = tid; i < kCacheItems; i += kThreads) {
    const unsigned top = ordered(sm.cache[i]) >> shift;
    win += top < pfx ? 1u : 0u;
    cand += top == pfx ? 1u : 0u;
  }
  block_sum2(sm, win, cand);

  if (native::elect()) {
    sm.win_base = native::atom_add_remote(native::remote(&sm.win_res, 0), win);
    const unsigned slot = native::remote(&sm.tally[2 * rank], 0);
    native::store_remote(slot, win);
    native::store_remote(slot + sizeof(unsigned),
        cand < kCandRegion ? cand : static_cast<unsigned>(kCandRegion));
  }
  if (tid == 0) {
    sm.emit = 0u;
    sm.cand_cursor = 0u;
  }
  __syncthreads();

  // `state.above` already holds the cluster-wide winner count, so the reserved
  // interval [win_base, win_base + win) is exactly the winner region.
  unsigned* region = sm.cand + rank * kCandRegion;
  #pragma unroll 1
  for (int i = tid; i < kCacheItems; i += kThreads) {
    const unsigned top = ordered(sm.cache[i]) >> shift;
    if (top < pfx) {
      const unsigned at = native::add_shared(&sm.emit, 1u);
      values[sm.win_base + at] = sm.cache[i];
      indices[sm.win_base + at] = static_cast<int64_t>(global_index(rank, static_cast<unsigned>(i)));
      continue;
    }
    if (top > pfx) continue;

    const unsigned at = native::add_shared(&sm.cand_cursor, 1u);
    if (at < kCandRegion) native::store_remote(native::remote(&region[at], 0),
        static_cast<unsigned>(i));
  }
  __syncthreads();

  native::sync();                       // gathered window and tallies landed

  if (rank == 0) {
    gather(sm, input);
    refine(sm, shift, sm.state.need, values, indices);
  }
}

// ===== kernel ===============================================================

__device__ __forceinline__ void load_cache(Shared& sm, const float* input, unsigned rank) {
  constexpr int kVecPerChunk = kChunkItems / 4;
  #pragma unroll
  for (int chunk = 0; chunk < kChunksPerCta; ++chunk) {
    const float4* src = reinterpret_cast<const float4*>(
        input + (rank + chunk * kBlocks) * kChunkItems);
    float4* dst = reinterpret_cast<float4*>(sm.cache + chunk * kChunkItems);
    #pragma unroll 1
    for (int i = threadIdx.x; i < kVecPerChunk; i += kThreads) dst[i] = src[i];
  }
}

__global__ void __launch_bounds__(kThreads, 1) select(const float* __restrict__ input,
    float* __restrict__ values, int64_t* __restrict__ indices) {
  __shared__ Shared sm;
  const unsigned rank = native::rank();

  if (native::elect()) {
    sm.state = {0u, 0u, static_cast<unsigned>(kSelected), 0u, 0u};
    sm.win_res = 0u;
  }
  #pragma unroll 1
  for (int i = threadIdx.x; i < kMaxPasses * kFieldBuckets; i += kThreads) {
    sm.hist[i] = 0u;
    sm.merge[i] = 0u;
  }
  __syncthreads();

  // Split barrier: rank 0'"'s zeroed accumulators must be cluster-visible before
  // any remote "'`red` lands in them. The wait overlaps the input load.
  native::arrive();
  load_cache(sm, input, rank);
  __syncthreads();
  native::wait();

  unsigned pfx = 0u;
  unsigned held = kLength;

  step<0>(sm, rank, pfx, held);
  if (held > kCandRegion) step<1>(sm, rank, pfx, held);
  if (held > kCandRegion) step<2>(sm, rank, pfx, held);
  if (held > kCandRegion) step<3>(sm, rank, pfx, held);

  const unsigned shift = (held > kCandRegion) ? 0u : kPassShift[0];
  emit_all(sm, rank, input, pfx, shift, values, indices);
}

}  // namespace topk
