// follows the barrier. A sparse digit costs one entry instead of 2048 slots,
// which is what keeps the fold cheap for the filtered passes.
template <int Pass>
__device__ __forceinline__ void publish(Shared& sm, unsigned rank) {
  if (native::elect()) sm.list = 0u;
  __syncthreads();

  unsigned* out = g_pairs[Pass & 1][rank];
  #pragma unroll
  for (int i = 0; i < kBucketsPerThread; ++i) {
    const int bucket = threadIdx.x + i * kThreads;
    const unsigned count = sm.hist[bucket];
    sm.hist[bucket] = 0u;
    if (count == 0) continue;

