// Radix Top-K selection for one [1, S] FP32 score row, distributed over an
// SM90 CTA cluster with a resident shared-memory copy of the input.
//
// Layout of the algorithm
// -----------------------
//   sweep A : global -> shared cache (float4), then an 11-bit radix histogram
//   merge   : remote "'`red` of each CTA histogram into rank 0'"'s accumulator
//   choose  : rank 0 block-scan finds the bucket holding the Kth key
//   emit    : strict winners go straight to their output slots through a remote
//             slot reservation; the threshold bucket's candidates are handed to
//             rank 0, which orders them and fills the remaining slots
//
// The radix loop stops as soon as the threshold bucket is small enough to
// gather, so a random row needs two passes instead of three, and the gathered
// candidates resolve the digits the loop skipped.
//
// "'`splitter` is the accumulated key prefix; lower encodings are better.
#pragma once

#include <cstdint>

#include "native.cuh"

namespace topk {

constexpr int kLength = 131072;
constexpr int kSelected = 2048;

constexpr int kThreads = 512;
constexpr int kBlocks = 16;
constexpr int kWarps = kThreads / 32;

constexpr int kChunkItems = 4096;
constexpr int kChunksPerCta = kLength / (kBlocks * kChunkItems);
constexpr int kCacheItems = kChunksPerCta * kChunkItems;

constexpr int kKeyBits = 32;
constexpr int kRadixBits = 11;
constexpr int kBuckets = 1 << kRadixBits;
constexpr int kBucketsPerThread = kBuckets / kThreads;
constexpr int kPasses = 3;

static_assert(kBlocks % 2 == 0);
static_assert(kCacheItems * kBlocks == kLength);
static_assert(kBuckets % kThreads == 0);

// Radix digit window per pass: bits [bit, bit + width).
constexpr int kPassBit[kPasses] = {21, 10, 0};
constexpr int kPassWidth[kPasses] = {11, 11, 10};
constexpr unsigned kPassMask[kPasses] = {0x7ffu, 0x7ffu, 0x3ffu};

static_assert(kPassBit[0] + kPassWidth[0] == kKeyBits);
static_assert(kPassBit[1] + kPassWidth[1] == kPassBit[0]);
static_assert(kPassBit[2] + kPassWidth[2] == kPassBit[1]);
static_assert(kPassBit[2] == 0);

// Threshold-bucket candidates rank 0 can gather. A random row leaves ~2''^9 keys
// in the 11-bit threshold bucket after two passes, and a full row leaves 2''^11.
constexpr int kCandCap = kSelected;
static_assert(kCandCap >= kSelected);

// Radix width of one refinement step on the gathered candidates.
constexpr int kRefineBits = 8;
constexpr int kRefineBuckets = 1 << kRefineBits;

// Order-preserving FP32 -> u32 map, inverted so that larger scores get smaller
// keys: the cumulative bucket scan then walks best-to-worst from bucket zero.
__device__ __forceinline__ unsigned ordered(float value) {
  const unsigned bits = __float_as_uint(value);
  const unsigned monotone =
      bits ''^ (static_cast<unsigned>(static_cast<int>(bits) >> 31) | 0x80000000u);
  return ~monotone;
}

struct State {
  unsigned bucket;
  unsigned above;
  unsigned need;
  unsigned cnt;
  unsigned stop;
};

struct alignas(16) Shared {
  unsigned hist[kPasses * kBuckets];
  unsigned merge[kPasses * kBuckets];
  State state;
  unsigned win_res;                     // rank 0: strict-winner slot cursor
  unsigned cand_res;                    // rank 0: candidate slot cursor
  unsigned win_base;                    // this CTA'"'s reserved winner interval
  unsigned cand_base;                   // this CTA's reserved candidate block
  unsigned win_cursor;                  // CTA-local slot cursors
  unsigned cand_cursor;
  unsigned out_cursor;                  // rank 0: refinement output cursor
  unsigned found[3];                    // rank 0: bucket, count above, count
  unsigned warp_totals[2 * kWarps];
  alignas(16) float cache[kCacheItems];
  alignas(16) float cand_val[kCandCap];
  unsigned cand_idx[kCandCap];
};

static_assert(kCacheItems % 4 == 0);

// ===== shared histogram =====================================================

template <int Pass>
__device__ __forceinline__ void histogram(Shared& sm, unsigned splitter) {
  unsigned* hist = sm.hist + Pass * kBuckets;
  constexpr int kBit = kPassBit[Pass];
  constexpr unsigned kMask = kPassMask[Pass];
  constexpr int kPriorBit = Pass == 0 ? 0 : kPassBit[Pass - 1];

  #pragma unroll 1
  for (int i = threadIdx.x; i < kCacheItems; i += kThreads) {
    const unsigned key = ordered(sm.cache[i]);
    if (Pass "'!= 0 && ((key >> kPriorBit) << kPriorBit) != splitter) continue;
    native::red_shared(hist + ((key >> kBit) & kMask));
  }
}

// rank 0: exclusive prefix over the merged histogram, pick the Kth bucket.
template <int Pass>
__device__ __forceinline__ void choose(Shared& sm) {
  const int tid = threadIdx.x;
  const unsigned need = sm.state.need;
  const unsigned above = sm.state.above;
  const unsigned* hist = sm.merge + Pass * kBuckets;

  // Contiguous ownership: thread `tid` holds buckets [tid*4, tid*4+4), so the
  // thread-order prefix scan below reproduces the bucket-order prefix.
  const int first = tid * kBucketsPerThread;
  unsigned counts[kBucketsPerThread];
  unsigned total = 0;
  #pragma unroll
  for (int i = 0; i < kBucketsPerThread; ++i) {
    counts[i] = hist[first + i];
    total += counts[i];
  }

  // Warp-level scan of the per-thread totals, then serially add earlier warps.
  unsigned inclusive = total;
  #pragma unroll
  for (int offset = 1; offset < 32; offset <<= 1)
    inclusive = native::scan_step(inclusive, offset);
  if ((tid % 32) == 31) sm.warp_totals[tid / 32] = inclusive;
  __syncthreads();

  unsigned running = inclusive - total;
  for (int warp = 0; warp < tid / 32; ++warp) running += sm.warp_totals[warp];

  // The bucket that holds the `need`-th best key; every earlier bucket is
  // strictly better and is fully selected. `running >= need` means the crossing
  // bucket lies in an earlier thread'"'s range, which owns the update.
  #pragma unroll
  for (int i = 0; i < kBucketsPerThread; ++i) {
    if (running >= need) break;
    if (running + counts[i] < need) {
      running += counts[i];
      continue;
    }
    sm.state.bucket = static_cast<unsigned>(first + i);
    sm.state.above = above + running;
    sm.state.need = need - running;
    sm.state.cnt = counts[i];
    sm.state.stop = (counts[i] == need - running) ? 1u : 0u;
    break;
  }
  __syncthreads();
}

// ===== one radix pass =======================================================

template <int Pass>
__device__ __forceinline__ void run_pass(Shared& sm, unsigned rank, unsigned& splitter,
    int& final_bit, bool& stop) {
  constexpr int kBit = kPassBit[Pass];

  histogram<Pass>(sm, splitter);
  __syncthreads();                      // local histograms complete and visible

  // Push this CTA's counts into rank 0's accumulator; later passes are sparse.
  const unsigned dst = native::remote(sm.merge + Pass * kBuckets, 0);
  const unsigned* hist = sm.hist + Pass * kBuckets;
  #pragma unroll
  for (int i = 0; i < kBucketsPerThread; ++i) {
    const int bucket = threadIdx.x + i * kThreads;
    const unsigned count = hist[bucket];
    if (count == 0) continue;
    native::red_remote(dst + bucket * sizeof(unsigned), count);
  }
  native::sync();                       // merged histogram complete

  if (rank == 0) choose<Pass>(sm);
  native::sync();                       // threshold published

  const unsigned base = native::remote(&sm.state, 0);
  const unsigned bucket = native::load_remote(base);
  stop = native::load_remote(base + 4 * sizeof(unsigned)) "'!= 0;
  splitter |= bucket << kBit;
  final_bit = kBit;
}

// ===== emission =============================================================

__device__ __forceinline__ void block_sum2(Shared& sm, unsigned& first, unsigned& second) {
  const int tid = threadIdx.x;
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    first += __shfl_down_sync(native::kWarpMask, first, offset);
    second += __shfl_down_sync(native::kWarpMask, second, offset);
  }
  if ((tid % 32) == 0) {
    sm.warp_totals[tid / 32] = first;
    sm.warp_totals[kWarps + tid / 32] = second;
  }
  __syncthreads();
  if (tid == 0) {
    unsigned a = 0;
    unsigned b = 0;
    #pragma unroll
    for (int warp = 0; warp < kWarps; ++warp) {
      a += sm.warp_totals[warp];
      b += sm.warp_totals[kWarps + warp];
    }
    sm.warp_totals[0] = a;
    sm.warp_totals[kWarps] = b;
  }
  __syncthreads();
  first = sm.warp_totals[0];
  second = sm.warp_totals[kWarps];
}

// rank 0: order the gathered threshold-bucket candidates and fill the remaining
// output slots. Walks down the bits the radix loop left unresolved; each step
// keeps the sub-bucket that holds the boundary, and stops as soon as that
// sub-bucket is exactly the rest of the selection.
__device__ __forceinline__ void refine(Shared& sm, unsigned splitter, unsigned lo,
    unsigned above, float* values, int64_t* indices) {
  const int tid = threadIdx.x;
  const unsigned total = sm.cand_res < kCandCap ? sm.cand_res : kCandCap;
  const unsigned limit = above + sm.state.need;

  if (tid == 0) sm.out_cursor = above;
  __syncthreads();

  unsigned hi = splitter;
  unsigned need = sm.state.need;
  while (lo > 0) {
    const unsigned width = lo < kRefineBits ? lo : kRefineBits;
    const unsigned bit = lo - width;
    const unsigned mask = (1u << width) - 1u;

    for (int i = tid; i < kRefineBuckets; i += kThreads) sm.hist[i] = 0u;
    __syncthreads();
    #pragma unroll 1
    for (unsigned i = tid; i < total; i += kThreads) {
      const unsigned key = ordered(sm.cand_val[i]);
      if ((key >> lo) != (hi >> lo)) continue;
      native::red_shared(sm.hist + ((key >> bit) & mask));
    }
    __syncthreads();

    // Exclusive prefix over the 256 sub-buckets; the owner of the bucket that
    // crosses `need` records it, exactly like `choose` does for the row.
    const unsigned mine = tid < kRefineBuckets ? sm.hist[tid] : 0u;
    unsigned inclusive = mine;
    #pragma unroll
    for (int offset = 1; offset < 32; offset <<= 1)
      inclusive = native::scan_step(inclusive, offset);
    if (tid < kRefineBuckets && (tid % 32) == 31) sm.warp_totals[tid / 32] = inclusive;
    __syncthreads();
    unsigned running = inclusive - mine;
    if (tid < kRefineBuckets) {
      for (int warp = 0; warp < tid / 32; ++warp) running += sm.warp_totals[warp];
      if (running < need && running + mine >= need) {
        sm.found[0] = static_cast<unsigned>(tid);
        sm.found[1] = running;
        sm.found[2] = mine;
      }
    }
    __syncthreads();
    const unsigned bucket = sm.found[0];
    const unsigned below = sm.found[1];

    // Everything in a better sub-bucket is selected outright.
    #pragma unroll 1
    for (unsigned i = tid; i < total; i += kThreads) {
      const unsigned key = ordered(sm.cand_val[i]);
      if ((key >> lo) != (hi >> lo)) continue;
      if (((key >> bit) & mask) >= bucket) continue;
      const unsigned slot = atomicAdd(&sm.out_cursor, 1u);
      if (slot < limit) {
        values[slot] = sm.cand_val[i];
        indices[slot] = sm.cand_idx[i];
      }
    }
    __syncthreads();

    hi |= bucket << bit;
    lo = bit;
    need -= below;
    if (sm.found[2] == need) break;      // the boundary sub-bucket is exact
  }

  // All remaining candidates share every resolved bit, so any `need` of them
  // completes the selection.
  #pragma unroll 1
  for (unsigned i = tid; i < total && need > 0; i += kThreads) {
    const unsigned key = ordered(sm.cand_val[i]);
    if ((key >> lo) != (hi >> lo)) continue;
    const unsigned slot = atomicAdd(&sm.out_cursor, 1u);
    if (slot >= limit) continue;
    values[slot] = sm.cand_val[i];
    indices[slot] = sm.cand_idx[i];
  }
}

// Emit strict winners into their reserved interval and forward the threshold
// bucket to rank 0. One reservation per CTA replaces the cluster-wide suffix
// exchange, and the single barrier afterwards only publishes the candidates.
__device__ __forceinline__ void emit(Shared& sm, unsigned rank, unsigned splitter,
    int final_bit, float* values, int64_t* indices) {
  const int tid = threadIdx.x;
  const unsigned above = sm.state.above;

  unsigned strict = 0;
  unsigned ties = 0;
  #pragma unroll 1
  for (int i = tid; i < kCacheItems; i += kThreads) {
    const unsigned key = (ordered(sm.cache[i]) >> final_bit) << final_bit;
    strict += key < splitter ? 1u : 0u;
    ties += key == splitter ? 1u : 0u;
  }
  block_sum2(sm, strict, ties);

  if (native::elect()) {
    sm.win_base = native::fetch_add_remote(native::remote(&sm.win_res, 0), strict);
    sm.cand_base = native::fetch_add_remote(native::remote(&sm.cand_res, 0), ties);
    sm.win_cursor = 0u;
    sm.cand_cursor = 0u;
  }
  __syncthreads();

  // Both regions are tiled by the reservations, so no exchange is needed: the
  // winner block is exact and the candidate block is only clipped when the
  // whole threshold bucket holds one value, where any `need` of them is valid.
  const unsigned win_base = sm.win_base;
  const unsigned cand_base = sm.cand_base;
  #pragma unroll 1
  for (int i = tid; i < kCacheItems; i += kThreads) {
    const float value = sm.cache[i];
    const unsigned key = (ordered(value) >> final_bit) << final_bit;
    if (key > splitter) continue;

    const unsigned index = static_cast<unsigned>(
        rank + (i / kChunkItems) * kBlocks) * kChunkItems + (i % kChunkItems);
    if (key < splitter) {
      const unsigned slot = win_base + atomicAdd(&sm.win_cursor, 1u);
      values[slot] = value;
      indices[slot] = index;
      continue;
    }
    const unsigned slot = cand_base + atomicAdd(&sm.cand_cursor, 1u);
    if (slot >= kCandCap) continue;
    native::store_remote(native::remote(&sm.cand_val[slot], 0), __float_as_uint(value));
    native::store_remote(native::remote(&sm.cand_idx[slot], 0), index);
  }

  native::sync();                       // candidates landed in rank 0

  if (rank == 0) refine(sm, splitter, final_bit, above, values, indices);
}

// ===== kernel ===============================================================

__device__ __forceinline__ void load_cache(Shared& sm, const float* input, unsigned rank) {
  constexpr int kVecPerChunk = kChunkItems / 4;
  #pragma unroll
  for (int chunk = 0; chunk < kChunksPerCta; ++chunk) {
    const float4* src = reinterpret_cast<const float4*>(
        input + (rank + chunk * kBlocks) * kChunkItems);
    float4* dst = reinterpret_cast<float4*>(sm.cache + chunk * kChunkItems);
    #pragma unroll 1
    for (int i = threadIdx.x; i < kVecPerChunk; i += kThreads) dst[i] = src[i];
  }
}

__global__ void __launch_bounds__(kThreads, 1) select(const float* __restrict__ input,
    float* __restrict__ values, int64_t* __restrict__ indices) {
  __shared__ Shared sm;
  const unsigned rank = native::rank();

  if (native::elect()) {
    sm.state = {0u, 0u, static_cast<unsigned>(kSelected), 0u, 0u};
    sm.win_res = 0u;
    sm.cand_res = 0u;
  }
  #pragma unroll 1
  for (int i = threadIdx.x; i < kPasses * kBuckets; i += kThreads) {
    sm.hist[i] = 0u;
    sm.merge[i] = 0u;
  }

  // One global sweep: the whole row lands in shared and stays resident.
  load_cache(sm, input, rank);
  __syncthreads();

  unsigned splitter = 0u;
  int final_bit = 0;
  bool stop = false;

  run_pass<0>(sm, rank, splitter, final_bit, stop);
  if (sm.state.cnt > kCandCap) run_pass<1>(sm, rank, splitter, final_bit, stop);
  if (sm.state.cnt > kCandCap) run_pass<2>(sm, rank, splitter, final_bit, stop);

  emit(sm, rank, splitter, final_bit, values, indices);
}

}  // namespace topk
